void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    // Normalizar las coordenadas del fragmento
    vec2 st = fragCoord.xy / iResolution.xy;

    // Obtener frecuencias del canal de audio
    float fftKit = texture(iChannel0, vec2(st.y, 0.1)).x;        // Frecuencia de los bajos (kit)
    float fftMelody = texture(iChannel0, vec2(st.y, 0.55)).x;    // Frecuencia de la melodía (medios-altos)
    float fftHighs = texture(iChannel0, vec2(st.y, 0.9)).x;      // Frecuencia de los agudos (altos)

    // Calcular la energía de las frecuencias
    float energyKit = fftKit;       // Energía de los bajos
    float energyMelody = fftMelody; // Energía de los medios-altos
    float energyHighs = fftHighs;   // Energía de los agudos

    // Establecer umbral para activar los efectos de color
    float audioThreshold = 0.05; // Umbral mínimo de energía para que los efectos se activen

    // Si todas las frecuencias están por debajo del umbral, no activar los efectos
    bool isAudioActive = (energyKit > audioThreshold || energyMelody > audioThreshold || energyHighs > audioThreshold);

    // Tiempo y posición del centro de la pantalla
    float time = iTime * 0.5;  // Escala de tiempo ajustada para animaciones más fluidas
    vec2 center = vec2(0.5, 0.5);  // Centro de la pantalla
    float distToCenter = distance(st, center);  // Distancia al centro

    // Si no hay audio, la pantalla debe ser oscura (negra)
    vec3 color = vec3(0.0); // Color negro por defecto (sin audio)

    // Si hay música activa, se aplican los efectos de color
    if (isAudioActive) {
        // Aplicar control de rango dinámico con ajuste para frecuencias altas
        float dynamicRangeKit = smoothstep(0.1, 0.6, energyKit);        // Suavizar transición de bajos
        float dynamicRangeMelody = smoothstep(0.1, 0.6, energyMelody);  // Suavizar transición de melodías
        float dynamicRangeHighs = smoothstep(0.2, 0.7, energyHighs);    // Suavizar transición de agudos

        // Efectos basados en frecuencias
        float kitEffect = fftKit * 0.9 * dynamicRangeKit;         // Respuesta de los bajos
        float melodyEffect = fftMelody * 0.6 * dynamicRangeMelody; // Respuesta de la melodía
        float highsEffect = fftHighs * 0.5 * dynamicRangeHighs;    // Respuesta de los agudos

        // Aportar colores según las frecuencias si la música está activa
        color += vec3(0.0, 1.0, 1.0) * kitEffect;      // Cian para los bajos (kit)
        color += vec3(0.6, 0.0, 1.0) * melodyEffect;   // Morado para la melodía (medios-altos)
        color += vec3(0.6, 1.0, 1.0) * highsEffect;    // Cian pálido para los agudos (altos)

        // Efecto blanco para los bajos (kit), con mayor precisión para frecuencias muy graves
        if (fftKit > 0.2) { // Ajustar umbral para los bajos solo si la música está activa
            vec3 bassColor = vec3(1.0); // Color blanco
            color += bassColor * smoothstep(0.5, 0.0, distToCenter) * dynamicRangeKit;
        }

        // Aportar brillo sutil a los agudos si la música está activa
        if (fftHighs > 0.3) {
            vec3 highColor = vec3(0.6, 1.0, 1.0); // Cian pálido brillante
            color += highColor * smoothstep(0.4, 0.0, distToCenter) * dynamicRangeHighs;
        }

        // Atenuación de la distancia al centro para crear efectos de profundidad
        color *= smoothstep(1.2, 0.0, distToCenter * 1.2);

        // Aumentar brillo general para niveles altos (máximos)
        color += 0.3 * smoothstep(0.7, 0.9, distToCenter);
    }

    // Salida del color con fondo negro si no hay música
    fragColor = vec4(color, 1.0);
}
